const StringPointerType = ?[*]const u8;
const KeyType = [:0]const u8;

pub fn CacheOutput(comptime ValueType: type) type {
        return union(enum) {
    unknown: void,
    not_set: void,
    value: ValueType,
};
}

pub fn CacheConfigurationType(comptime CtorOptionsType: type) type {
        return struct {
    var_name: []const u8,
    opts: CtorOptionsType,
};
}

pub fn StringCache(comptime ip: StringInput) type {
        _ = ip;
        return struct {
    ptr_value: std.atomic.Value(StringPointerType) = std.atomic.Value(StringPointerType).init(null),
    len_value: std.atomic.Value(LenType) = std.atomic.Value(LenType).init(std.math.maxInt(LenType)),

pub fn getCached(self: *@This()) StringOutput {
            const len = self.len_value.load(.acquire);
            if ((len == Self.not_loaded_len)) {
                return .unknown;
            }
            if ((len == Self.not_set_len)) {
                return .not_set;
            }
            const ptr = self.ptr_value.load(.monotonic);
            return StringOutput{ .value = (blk: {
            break :blk ptr.?[0..len];

}) };
    }

pub inline fn deserAndInvalidate(self: *@This(), raw_env: ?[]const u8) ?[]const u8 {
            if (raw_env) |ev| {
                _ = &ev;
                _ = self.ptr_value.store(ev.ptr, .monotonic);
                _ = self.len_value.store(ev.len, .release);
            } else {
                _ = self.ptr_value.store(null, .monotonic);
                _ = self.len_value.store(Self.not_set_len, .release);
            }
            return raw_env;
    }
    const Self = @This();
    const LenType = usize;
    const not_loaded_len: LenType = std.math.maxInt(LenType);
    const not_set_len: LenType = std.math.maxInt(LenType) - 1;
};
}

pub fn stringIsTruthyImpl(s: []const u8) bool {
        const false_values: [5][]const u8 = .{ "", "0", "false", "no", "off" };
        inline for (false_values) |tv| {
            if (std.ascii.eqlIgnoreCase(s, tv)) {
                return false;
            }
        }
        return true;
}

pub fn BoolCache(comptime ip: BoolInput) type {
        return struct {
    value: std.atomic.Value(BoolStoredType) = std.atomic.Value(BoolStoredType).init(.unknown),

pub inline fn getCached(self: *@This()) BoolOutput {
            _ = ip;
            const cached = self.value.load(.monotonic);
            switch (cached) {
.unknown => {
@branchHint(.unlikely);
            return .unknown;
},
.not_set => {
return .not_set;
},
.no => {
return BoolOutput{ .value = false };
},
.yes => {
return BoolOutput{ .value = true };
},
}
    }

pub inline fn deserAndInvalidate(self: *@This(), raw_env: ?[]const u8) ?bool {
            if ((raw_env == null)) {
                _ = self.value.store(.not_set, .monotonic);
                return null;
            }
            const string_is_truthy = stringIsTruthyImpl(raw_env.?);
            _ = self.value.store((if (string_is_truthy) .yes else .no), .monotonic);
            return string_is_truthy;
    }
    const Self = @This();
};
}

pub fn UnsignedCache(comptime ip: UnsignedInput) type {
        return struct {
    value: std.atomic.Value(StoredType) = std.atomic.Value(StoredType).init(Self.unknown_sentinel),

pub inline fn getCached(self: *@This()) UnsignedOutput {
            switch (self.value.load(.monotonic)) {
Self.unknown_sentinel => {
@branchHint(.unlikely);
            return .unknown;
},
Self.not_set_sentinel => {
return .not_set;
},
else => |v| {
return UnsignedOutput{ .value = v };
},
}
    }

pub inline fn deserAndInvalidate(self: *@This(), raw_env: ?[]const u8) ?u64 {
            if ((raw_env == null)) {
                _ = self.value.store(Self.not_set_sentinel, .monotonic);
                return null;
            }
            if (std.mem.eql(u8, raw_env.?, "")) {
                switch (ip.opts.deser.empty_string_as) {
.value => |v| {
_ = self.value.store(v, .monotonic);
                return v;
},
.erroneous => {
return self.handleError(raw_env.?, "is an empty string");
},
}
            }
            const formatted = (blk_catch_0: { break :blk_catch_0 ((std.fmt.parseInt(StoredType, raw_env.?, 10)) catch |err| { _ = &err; break :blk_catch_0 (switch (err) {
error.Overflow => {
return self.handleError(raw_env.?, "overflows u64");
},
error.InvalidCharacter => {
return self.handleError(raw_env.?, "is not a valid integer");
},
}); }); });
            if (((formatted == Self.not_set_sentinel) or (formatted == Self.unknown_sentinel))) {
                return self.handleError(raw_env.?, "is a reserved value");
            }
            _ = self.value.store(formatted, .monotonic);
            return formatted;
    }

pub fn handleError(self: *@This(), raw_env: []const u8, comptime reason: []const u8) ?u64 {
            const base_fmt: []const u8 = "Environment variable '{s}' has value '{s}' which ";
            const fmt = std.fmt.comptimePrint("{s}{s}.", .{ base_fmt, reason });
            const missing_default_fmt: []const u8 = "Environment variable '{s}' is configured to fallback to default on {s}, but no default is set.";
            switch (ip.opts.deser.error_handling) {
.debug_warn => {
_ = bun.Output.debugWarn(fmt, .{ ip.var_name, raw_env });
            _ = self.value.store(Self.not_set_sentinel, .monotonic);
            return null;
},
.not_set => {
_ = self.value.store(Self.not_set_sentinel, .monotonic);
            return null;
},
.truthy_cast => {
if (stringIsTruthyImpl(raw_env)) {
                _ = self.value.store(1, .monotonic);
                return 1;
            } else {
                _ = self.value.store(0, .monotonic);
                return 0;
            }
},
.default_fallback => {
if (comptime (ip.opts.default != null)) {
                const d = ip.opts.default.?;
                _ = self.value.store(d, .monotonic);
                return d;
            }
            _ = @compileError(std.fmt.comptimePrint(missing_default_fmt, .{ ip.var_name, "default_fallback" }));
},
}
    }
    const Self = @This();
    const StoredType = u64;
    const unknown_sentinel: comptime_int = std.math.maxInt(StoredType);
    const not_set_sentinel: comptime_int = std.math.maxInt(StoredType) - 1;
};
}

pub fn New(comptime VariantType: type, comptime key: [:0]const u8, comptime opts: VariantType.CtorOptions) type {
        return PlatformSpecificNew(VariantType, key, key, opts);
}

pub fn PlatformSpecificCore(comptime VariantType: type, comptime posix_key: ?KeyType, comptime windows_key: ?KeyType, comptime opts: VariantType.CtorOptions) type {
        const comptime_key: []const u8 = (if ((posix_key != null)) posix_key.? else (if ((windows_key != null)) windows_key.? else "<unknown>"));
        if (((posix_key == null) and (windows_key == null))) {
            _ = @compileError(std.fmt.comptimePrint("Environment variable {s} has no keys for POSIX nor Windows specified. Provide a key for either POSIX or Windows.", .{ comptime_key }));
        }
        const ValueType = VariantType.ValueType;
        const CacheType = VariantType.Cache(VariantType.Input{ .var_name = comptime_key, .opts = opts });
        return struct {
    pub var cache: CacheType = CacheType{  };

pub fn platformGet() ?ValueType {
            const platform_key: ?KeyType = (if (comptime bun.Environment.isPosix) posix_key else (if (comptime bun.Environment.isWindows) windows_key else null));
            const k = ((platform_key) orelse { return null; });
            switch (Self.cache.getCached()) {
.unknown => {
@branchHint(.unlikely);
            const env_var = bun.getenvZ(k);
            const maybe_reloaded = Self.cache.deserAndInvalidate(env_var);
            if (maybe_reloaded) |v| {
                _ = &v;
                return v;
            }
            if (opts.default) |d| {
                _ = &d;
                return d;
            }
            return null;
},
.not_set => {
if (opts.default) |d| {
                _ = &d;
                return d;
            }
            return null;
},
.value => |v| {
return v;
},
}
    }

pub fn key() KeyType {
            _ = Self.assertPlatformSupported();
            return (Self.platformKey()).?;
    }

pub fn platformKey() ?KeyType {
            if (bun.Environment.isPosix) {
                return posix_key;
            }
            if (bun.Environment.isWindows) {
                return windows_key;
            }
            return null;
    }

pub fn getRaw() ?ValueType {
            _ = Self.assertPlatformSupported();
            const cached_result = Self.cache.getCached();
            switch (cached_result) {
.unknown => {
@branchHint(.unlikely);
            return Self.getForceReloadRaw();
},
.not_set => {
return null;
},
.value => |v| {
return v;
},
}
    }

pub fn getForceReloadRaw() ?ValueType {
            _ = Self.assertPlatformSupported();
            const env_var = bun.getenvZ(Self.key());
            return Self.cache.deserAndInvalidate(env_var);
    }

pub fn assertPlatformSupported() void {
            const missing_key_fmt: []const u8 = "Cannot retrieve the value of {s} for {s} since no {s} key is associated with it.";
            if (comptime (bun.Environment.isWindows and (windows_key == null))) {
                _ = @compileError(std.fmt.comptimePrint(missing_key_fmt, .{ comptime_key, "Windows", "Windows" }));
            } else {
                if (comptime (bun.Environment.isPosix and (posix_key == null))) {
                    _ = @compileError(std.fmt.comptimePrint(missing_key_fmt, .{ comptime_key, "POSIX", "POSIX" }));
                }
            }
    }
    const Self = @This();
};
}

pub fn PlatformSpecificNew(comptime VariantType: type, comptime posix_key: ?KeyType, comptime windows_key: ?KeyType, comptime opts: VariantType.CtorOptions) type {
        const ValueType = VariantType.ValueType;
        const Core = PlatformSpecificCore(VariantType, posix_key, windows_key, opts);
        if (comptime (opts.default != null)) {
            const default_val: ValueType = opts.default.?;
            return struct {

pub fn get() ValueType {
            return ((Core.getRaw()) orelse (default_val));
    }
    pub const platformGet = Core.platformGet;
    pub const key = Core.key;
    pub const platformKey = Core.platformKey;
    pub const default: ValueType = default_val;
};
        } else {
            return struct {

pub fn get() ?ValueType {
            return Core.getRaw();
    }

pub fn getNotEmpty() ?ValueType {
            if (Core.getRaw()) |v| {
                _ = &v;
                if ((v.len == 0)) {
                    return null;
                }
                return v;
            }
            return null;
    }
    pub const platformGet = Core.platformGet;
    pub const key = Core.key;
    pub const platformKey = Core.platformKey;
    pub const default: void = {};
};
        }
}

pub fn newFeatureFlag(comptime env_var: [:0]const u8) type {
        return New(kind.boolean, env_var, BoolCtorOptions{ .default = false });
}

pub fn newFeatureFlagOpt(comptime env_var: [:0]const u8) type {
        return New(kind.boolean, env_var, BoolCtorOptions{ .default = null });
